// lib/content.ts — Build-time static content loader and Markdown renderer.
// Reads content/manifest.json and Markdown files generated by scripts/sync_docs.py
// so Next.js + NES emits 100% static HTML pages with zero runtime network requests.

import fs from "fs";
import path from "path";

export type DocTrack = "docs" | "guides";

export interface TocItem {
	level: number;
	text: string;
	id: string;
}

export interface DocPageMeta {
	slug: string;
	track: DocTrack;
	section?: string;
	title: string;
	sourcePath: string;
	sourceBranch: string;
	localFile: string;
	toc: TocItem[];
}

export interface ProjectRecord {
	id: string;
	name: string;
	repo: string;
	repoUrl: string;
	originalSiteUrl: string;
	branch: string;
	established: boolean;
	status: string;
	version: string;
	badge: string;
	accentColor?: string;
	rebaseNotice: string | null;
	description: string;
	tracks: DocTrack[];
	syncedSha: string | null;
	pages: DocPageMeta[];
}

export interface DocsManifest {
	generatedAt: string;
	license: {
		name: string;
		fullName: string;
		url: string;
		summary: string;
	};
	projects: ProjectRecord[];
}

const CONTENT_ROOT = path.join(process.cwd(), "content");
const MANIFEST_PATH = path.join(CONTENT_ROOT, "manifest.json");

/** Load the build-time compiled manifest generated by scripts/sync_docs.py. */
export function loadManifest(): DocsManifest {
	const raw = fs.readFileSync(MANIFEST_PATH, "utf-8");
	return JSON.parse(raw) as DocsManifest;
}

/** Find a project by its slug ID. */
export function getProject(projectId: string): ProjectRecord | undefined {
	return loadManifest().projects.find((p) => p.id === projectId);
}

/** Read the raw Markdown string for a static doc or guide page. */
export function readPageMarkdown(localFile: string): string {
	const absPath = path.join(process.cwd(), localFile);
	if (!fs.existsSync(absPath)) {
		return "# Page Not Found\n\nThis static page has not been generated yet.";
	}
	return fs.readFileSync(absPath, "utf-8");
}

function escapeHtml(value: string): string {
	return value
		.replace(/&/g, "&amp;")
		.replace(/</g, "&lt;")
		.replace(/>/g, "&gt;")
		.replace(/"/g, "&quot;");
}

function slugify(value: string): string {
	return (
		value
			.replace(/[^a-zA-Z0-9\s-]/g, "")
			.trim()
			.toLowerCase()
			.replace(/[\s_-]+/g, "-") || "section"
	);
}

/** Format inline Markdown tokens including rewritten /<project>/<slug> & #-es links. */
function renderInline(text: string): string {
	let out = escapeHtml(text);
	out = out.replace(/`([^`]+)`/g, "<code>$1</code>");
	out = out.replace(/\*\*([^*]+)\*\*/g, "<strong>$1</strong>");
	out = out.replace(/\*([^*]+)\*/g, "<em>$1</em>");
	out = out.replace(/\[([^\]]+)\]\(([^)]+)\)/g, (_m, label: string, href: string) => {
		if (href.startsWith("http://") || href.startsWith("https://")) {
			return `<a href="${href}" target="_blank" rel="noopener noreferrer">${label}</a>`;
		}
		return `<a href="${href}">${label}</a>`;
	});
	return out;
}

/**
 * Build-time Markdown renderer with deterministic IDs for EngineScroll links.
 * Supports GFM-style tables, ordered lists, and horizontal rules.
 */
function splitTableRow(row: string): string[] {
	let value = row.trim();
	if (value.startsWith("|")) value = value.slice(1);
	if (value.endsWith("|")) value = value.slice(0, -1);
	return value.split(/(?<!\\)\|/).map((cell) => cell.trim().replace(/\\\|/g, "|"));
}

function isTableRow(line: string): boolean {
	return line.includes("|") && splitTableRow(line).length > 1;
}

function isTableSeparator(line: string): boolean {
	const cells = splitTableRow(line);
	return cells.length > 1 && cells.every((cell) => /^:?-{3,}:?$/.test(cell));
}

function nextNonEmptyLine(lines: string[], start: number): number {
	for (let index = start; index < lines.length; index += 1) {
		if (lines[index].trim() !== "") return index;
	}
	return -1;
}

function renderTableAlignment(separator: string): string[] {
	return splitTableRow(separator).map((cell) => {
		if (cell.startsWith(":") && cell.endsWith(":")) return "center";
		if (cell.endsWith(":")) return "right";
		return "left";
	});
}

export function renderMarkdown(markdown: string): string {
	const lines = markdown.replace(/\r\n?/g, "\n").split("\n");
	const html: string[] = [];
	let inCode = false;
	let codeLang = "text";
	let codeLines: string[] = [];
	let activeList: "ul" | "ol" | null = null;
	let lineNum = 0;

	const flushList = () => {
		if (activeList) {
			html.push("</" + activeList + ">");
			activeList = null;
		}
	};

	const renderCodeBlock = () => {
		lineNum += 1;
		html.push(
			'<div id="L' + lineNum + '" class="kd-code-wrap" data-lang="' + escapeHtml(codeLang) + '">' +
				'<div class="kd-code-head"><span>' + escapeHtml(codeLang) + '</span>' +
				'<button type="button" class="kd-copy-btn" data-copy="true">Copy</button></div>' +
				"<pre><code>" + escapeHtml(codeLines.join("\n")) + "</code></pre></div>",
		);
	};

	for (let index = 0; index < lines.length; index += 1) {
		const line = lines[index];

		if (/^\s*\x60\x60\x60/.test(line)) {
			flushList();
			if (!inCode) {
				inCode = true;
				codeLang = line.replace(/^\s*\x60\x60\x60/, "").trim() || "text";
				codeLines = [];
			} else {
				renderCodeBlock();
				inCode = false;
			}
			continue;
		}

		if (inCode) {
			codeLines.push(line);
			continue;
		}

		const headingMatch = line.match(/^(#{1,6})\s+(.+)$/);
		if (headingMatch) {
			flushList();
			const level = headingMatch[1].length;
			const rawHeading = headingMatch[2].trim();
			const id = slugify(rawHeading);
			html.push("<h" + level + ' id="' + id + '">' + renderInline(rawHeading) + "</h" + level + ">");
			continue;
		}

		const separatorIndex = nextNonEmptyLine(lines, index + 1);
		if (isTableRow(line) && separatorIndex >= 0 && isTableSeparator(lines[separatorIndex])) {
			flushList();
			const headers = splitTableRow(line);
			const alignments = renderTableAlignment(lines[separatorIndex]);
			const columnCount = Math.max(headers.length, alignments.length);
			html.push('<div class="kd-table-wrap"><table class="kd-markdown-table"><thead><tr id="L' + (++lineNum) + '">');
			for (let column = 0; column < columnCount; column += 1) {
				const align = alignments[column] || "left";
				html.push('<th scope="col" style="text-align:' + align + '">' + renderInline(headers[column] || "") + "</th>");
			}
			html.push("</tr></thead><tbody>");

			let cursor = separatorIndex + 1;
			while (cursor < lines.length) {
				if (lines[cursor].trim() === "") {
					const nextRow = nextNonEmptyLine(lines, cursor + 1);
					if (nextRow >= 0 && isTableRow(lines[nextRow])) cursor = nextRow;
					else {
						cursor += 1;
						break;
					}
				}
				if (cursor >= lines.length || !isTableRow(lines[cursor]) || isTableSeparator(lines[cursor])) break;
				const cells = splitTableRow(lines[cursor]);
				html.push('<tr id="L' + (++lineNum) + '">');
				for (let column = 0; column < columnCount; column += 1) {
					const align = alignments[column] || "left";
					html.push('<td style="text-align:' + align + '">' + renderInline(cells[column] || "") + "</td>");
				}
				html.push("</tr>");
				cursor += 1;
			}
			html.push("</tbody></table></div>");
			index = cursor - 1;
			continue;
		}

		if (/^\s*(?:---+|\*\*\*|___)\s*$/.test(line)) {
			flushList();
			html.push('<hr class="kd-markdown-rule">');
			continue;
		}

		const quoteMatch = line.match(/^\s*>\s?(.*)$/);
		if (quoteMatch) {
			flushList();
			lineNum += 1;
			html.push('<blockquote id="L' + lineNum + '" class="kd-callout">' + renderInline(quoteMatch[1]) + "</blockquote>");
			continue;
		}

		const listMatch = line.match(/^\s*(?:([-*+])|(\d+)[.)])\s+(.+)$/);
		if (listMatch) {
			const nextListType = listMatch[2] ? "ol" : "ul";
			if (activeList !== nextListType) {
				flushList();
				activeList = nextListType;
				html.push("<" + activeList + ">");
			}
			lineNum += 1;
			html.push('<li id="L' + lineNum + '">' + renderInline(listMatch[3]) + "</li>");
			continue;
		}

		if (line.trim() === "") {
			flushList();
			continue;
		}

		flushList();
		lineNum += 1;
		html.push('<p id="L' + lineNum + '">' + renderInline(line.trim()) + "</p>");
	}

	if (inCode) renderCodeBlock();
	flushList();
	return html.join("\n");
}
